# Affected: production services that transitively depend on the retiring package via modules
affected_query = """
WITH RECURSIVE retiring AS (
  SELECT trp.object_id AS package_id,
         ttd.object_id AS deployment_id
  FROM task_retires_package trp
  JOIN task_targets_deployment ttd ON ttd.subject_id = trp.subject_id
  WHERE trp.subject_id = 'task:identity-platform-legacy-cutover'
),
package_modules AS (
  SELECT mdop.subject_id AS module_id
  FROM module_depends_on_package mdop
  JOIN retiring r ON mdop.object_id = r.package_id
),
module_closure AS (
  SELECT module_id FROM package_modules
  UNION
  SELECT mdom.subject_id AS module_id
  FROM module_depends_on_module mdom
  JOIN module_closure mc ON mdom.object_id = mc.module_id
)
SELECT DISTINCT sim.subject_id AS service_id
FROM service_implements_module sim
JOIN module_closure mc ON sim.object_id = mc.module_id
JOIN service_deployed_to_deployment sdd ON sdd.subject_id = sim.subject_id
JOIN retiring r ON sdd.object_id = r.deployment_id
ORDER BY service_id
"""

covered_query = """
WITH RECURSIVE retiring AS (
